INSERT INTO question_bank (
    id, category_id, question_type, question_text, options, correct_answer,
    explanation, difficulty_level, created_by, status, school_id, stage_id, create_time, update_time
) VALUES (
    NULL, 1168, 'OPERATION', '请在打开的EXCEL的电子表格中，进行下列操作，完成操作后，请保存文件，并关闭EXCEL。（共35分）（1）在“进出库存表”中的A1单元格中输入表格标题：电商竞销存，设置标题字体格式为：黑体、20，将“A1:F1”单元格设置合并及居中；（5分）（2）在A4单元格中输入内容“SZDM20140501”，并利用填充柄将区域填充完整；（2分）（3）利用MID函数提取每个产品名称并按照对应关系将结果填入到“B4:B16”单元格中（对应关系为：产品代码第11-12位代表产品名称）；（4分）（4）利用公式计算出1日与2日的剩余库存量（剩余库存量=入库-出库），并将结果分别填入到C18和E18单元格中，设置“C18:E18”单元格的数据类型为数值，不保留小数；（8分）（5）选择“B2:F16”单元格，创建簇状柱形图，并添加图表标题为：1日-2日产品对比图；（4分）（6）设置纵坐标轴的最小值为：固定值1000，最大值为：固定值7000；（4分）（7）设置簇状柱形图的表样式为：样式7；（2分）（8）将“Sheet2”工作表重命名为“统计表”；（2分）（9）将“进出库存表”中“C2:F16”单元格区域的值转置到“统计表”中，以A2单元格为起点位置放置；（2分）（10）对“统计表”进行页面设置，设置工作表打印加“网格线”。（2分）请参看样张：样张1样张2',
    '[]', '', '', 3, 1, 1, 1, 4, NOW(), NOW()
);
INSERT INTO question_bank (
    id, category_id, question_type, question_text, options, correct_answer,
    explanation, difficulty_level, created_by, status, school_id, stage_id, create_time, update_time
) VALUES (
    NULL, 1168, 'OPERATION', '请在打开的EXCEL的电子表格中，进行下列操作，完成操作后，请保存文件，并关闭EXCEL。（共35分）（1）在“采购表”中设置表格标题字体格式为：仿宋或仿宋_GB2312、24、加粗，将“A1:F1”单元格设置为：合并及居中；（5分）（2）设置表格第一行的行高为30，第二行行高为28，其余行行高为25；（3分）（3）将“采购时间”列的“E3:E23”单元格区域设置为日期（*2001-03-14）类型；（2分）（4）将“采购时间”列“E3:E23”单元格区域的数据有效性设置为日期（介于2018-3-1到2018-11-1之间）；（2分）（5）在“采购表”中按照主要关键字“折扣”降序，次要关键字“单价/元”升序对数据进行排序；（2分）（6）利用公式计算出采购商品的总价（总价=采购数量*单价），结果填入到“F3:F23”单元格中，将“A3:F23”字体格式设置为：仿宋或仿宋_GB2312、13；（4分）（7）将“采购表”的“A2:D23”内容复制到“折扣表”中，以A1为起点位置放置，在E1单元格中输入“折后价”文本内容；（4分）（8）利用公式计算折后价（折后价=单价*折扣），结果填入到“E2:E22”单元格中，并保留一位小数；（4分）（9）利用条件函数SUMIF统计项目中含“裤”的项目数量之和以及折后价大于100的单价之和，将结果分别填入到M8和M9单元格中；（4分）（10）在“折扣表”中，选择“A1:B22”、“D1:D22”单元格，创建三维簇状柱形图，坐标轴标题X轴为：项目，Y轴为：价格，不显示图例，添加图表标题为：采购情况图。（5分）请参看样张：样张1样张2',
    '[]', '', '', 3, 1, 1, 1, 4, NOW(), NOW()
);
